export const mkR = (
  s: Record<CatKey, number>,
  o: Partial<Record<NanoKey, number>> = {},
): Record<NanoKey, number> => {
  const r = {} as Record<NanoKey, number>;
  CATS.forEach((c) =>
    c.n.forEach(([k]) => {
      r[k] = Math.round((s[c.k] - 50) / 2.45);
    }),
  );
  return { ...r, ...o };
};

