export const E0: HeziEventItem[] = [
  {
    id: 1,
    t: "Pelada Oficial Hezi",
    tp: "Pelada",
    q: "Sábado · 17:00",
    l: "Quadra Central",
    r: "Regras Fiba, 7 pontos ou 7 minutos",
    f: [1, 12, 2],
    rewardedUids: [1, 12, 2],
  },
];

function normalizeEvents(evs: HeziEventItem[]): HeziEventItem[] {
  return evs.map((e) => ({
    ...e,
    r:
      e.r === "Jogos até 12 pontos ou 10 min"
        ? "Regras Fiba, 7 pontos ou 7 minutos"
        : e.r,
    rewardedUids: Array.isArray(e.rewardedUids)
      ? e.rewardedUids
      : Array.from(new Set(e.f || [])),
  }));
}

export interface HeziPlatformState {
  lastModified: number;
  users: HeziUser[];
  evs: HeziEventItem[];
  notifications: HeziNotification[];
  updUser: (id: number, patch: Partial<HeziUser>) => void;
  addUser: (u: HeziUser) => void;
  setEvs: (evs: HeziEventItem[]) => void;
  addQueue: (eid: number, uid: number) => void;
  removeQueue: (eid: number, uid: number) => void;
  markEventRewarded: (eid: number, uid: number) => void;
  addNotification: (n: HeziNotification) => void;
  updateNotification: (id: string, patch: Partial<HeziNotification>) => void;
  setNotifications: (list: HeziNotification[]) => void;
  hydrateFromRemote: (
    remote: Partial<
      Pick<HeziPlatformState, "lastModified" | "users" | "evs" | "notifications">
    >,
  ) => void;
}

export const useHeziPlatform = create<HeziPlatformState>()(
  persist(
    (set) => ({
      lastModified: 0,
      users: U0,
      evs: E0,
      notifications: [],

      updUser: (id, patch) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          users: s.users.map((x) => (x.id === id ? { ...x, ...patch } : x)),
        })),

      addUser: (u) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          users: [...s.users, u],
        })),

      setEvs: (evs) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          evs: normalizeEvents(evs),
        })),

      addQueue: (eid, uid) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          evs: s.evs.map((e) =>
            e.id === eid && !e.f.includes(uid) ? { ...e, f: [...e.f, uid] } : e,
          ),
        })),

      removeQueue: (eid, uid) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          evs: s.evs.map((e) =>
            e.id === eid ? { ...e, f: e.f.filter((id) => id !== uid) } : e,
          ),
        })),

      markEventRewarded: (eid, uid) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          evs: s.evs.map((e) => {
            if (e.id !== eid) return e;
            const prev = e.rewardedUids || [];
            if (prev.includes(uid)) return e;
            return { ...e, rewardedUids: [...prev, uid] };
          }),
        })),

      addNotification: (n) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          notifications: [n, ...s.notifications].slice(0, 150),
        })),

      updateNotification: (id, patch) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          notifications: s.notifications.map((n) =>
            n.id === id ? { ...n, ...patch } : n,
          ),
        })),

      setNotifications: (list) =>
        set((s) => ({
          ...s,
          lastModified: Date.now(),
          notifications: list,
        })),

      hydrateFromRemote: (remote) =>
        set((s) => ({
          ...s,
          ...remote,
          evs: remote.evs ? normalizeEvents(remote.evs) : s.evs,
          notifications: remote.notifications ?? s.notifications,
        })),
    }),
    {
      name: "hezi-platform-store-v6",
      partialize: (s) => ({
        lastModified: s.lastModified,
        users: s.users,
        evs: s.evs,
        notifications: s.notifications,
      }),
    },
  ),
);

export type SessionId = "visitante" | "prof" | "admin" | number;

interface SessionStore {
  sid: SessionId;
  setSid: (sid: SessionId) => void;
}

export const useHeziSession = create<SessionStore>()(
  persist(
    (set) => ({
      sid: "visitante",
      setSid: (sid) => set({ sid }),
    }),
    {
      name: "hezi-session-device-v3",
    },
  ),
);
